using FluentEmail.Core;
using FluentEmail.Smtp;

var sender = new SmtpSender(new SmtpClient()
{
    Host = "smtp.example.com",
    Port = 587,
    Credentials = new NetworkCredential("user", "pass")
});

Email.DefaultSender = sender;

var response = await new Email("from@example.com")
    .To("to@example.com")
    .Subject("Welcome!")
    .Body("Thanks for signing up.")
    .SendAsync();

if (response.Success)
    Console.WriteLine("Email sent!");
else
    Console.WriteLine("Failed: " + response.ErrorMessages.First());

// Install FluentEmail.Razor first
// Then register the renderer
builder.Services
    .AddFluentEmail("from@example.com")
    .AddRazorRenderer();

// Usage
var email = new Email("to@example.com")
    .Subject("Order Confirmation")
    .UsingTemplateFromEmbedded(
        "MyApp.EmailTemplates.OrderConfirmation",
        new { OrderId = 123, Total = 49.99m }
    );

await email.SendAsync();
